// Pull the 11 character video ID out of any YouTube link format.
const url = String($json.videoUrl || '').trim();

const patterns = [
  /[?&]v=([A-Za-z0-9_-]{11})/,      // watch?v=ID
  /youtu\.be\/([A-Za-z0-9_-]{11})/, // youtu.be/ID
  /\/shorts\/([A-Za-z0-9_-]{11})/,  // /shorts/ID
  /\/live\/([A-Za-z0-9_-]{11})/,    // /live/ID
  /\/embed\/([A-Za-z0-9_-]{11})/    // /embed/ID
];

let videoId = null;
for (const p of patterns) {
  const m = url.match(p);
  if (m) { videoId = m[1]; break; }
}

if (!videoId) {
  throw new Error('Could not read a video ID from this link: ' + url);
}

return [{
  json: {
    videoId,
    videoUrl: url,
    cleanUrl: 'https://www.youtube.com/watch?v=' + videoId,
    apiToken: $json.apiToken,
    driveFolderId: $json.driveFolderId,
    rowNumber: $json.rowNumber
  }
}];

const meta = $('Extract Video ID').item.json;

const raw = ($json && ($json.body ?? $json.data)) ?? null;

let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [{ json: { ...meta, status: 'error', text: null, error: 'The transcript API sent back something that is not valid JSON.' } }];
}

// The API has shipped a few different shapes over time. Cover them all.
const first = Array.isArray(parsed)
  ? parsed[0]
  : (Array.isArray(parsed?.data) ? parsed.data[0] : (parsed?.data ?? parsed));

let text = first?.text ?? first?.transcript ?? null;

// Shape: tracks[0].transcript = [{ text, start, dur }, ...]
if (!text && Array.isArray(first?.tracks?.[0]?.transcript)) {
  text = first.tracks[0].transcript.map(t => t.text).join(' ');
}

// Shape: transcript already an array of segments
if (Array.isArray(text)) {
  text = text.map(t => (typeof t === 'string' ? t : t.text)).join(' ');
}

const title = first?.title
  ?? first?.microformat?.playerMicroformatRenderer?.title?.simpleText
  ?? first?.videoDetails?.title
  ?? null;

const channel = first?.author
  ?? first?.videoDetails?.author
  ?? first?.microformat?.playerMicroformatRenderer?.ownerChannelName
  ?? null;

const language = first?.language ?? first?.lang ?? first?.tracks?.[0]?.language ?? null;

return [{
  json: {
    ...meta,
    title,
    channel,
    language,
    text,
    status: text ? 'found' : 'no_transcript'
  }
}];

const d = $json;

let text = typeof d.text === 'string' ? d.text : JSON.stringify(d.text);

// Tidy up without losing anything.
text = text
  .replace(/&(amp;)?#39;/g, "'")
  .replace(/&(amp;)?quot;/g, '"')
  .replace(/&(amp;)?#(34|39);/g, "'")
  .replace(/&amp;/g, '&')
  .replace(/\r?\n/g, ' ')
  .replace(/\[(music|applause|laughter|mÃºsica|musica|aplausos)\]/gi, '')
  .replace(/\s+/g, ' ')
  .trim();

// Break the wall of text into readable paragraphs of ~5 sentences.
const sentences = text.match(/[^.!?]+[.!?]+|\S+$/g) || [text];
const paragraphs = [];
for (let i = 0; i < sentences.length; i += 5) {
  paragraphs.push(sentences.slice(i, i + 5).join(' ').trim());
}
const bodyText = paragraphs.join('\n\n');

const wordCount = text.split(' ').filter(Boolean).length;
const readingMinutes = Math.max(1, Math.round(wordCount / 150));

const title = d.title || ('YouTube Video ' + d.videoId);
const stamp = new Date().toISOString().slice(0, 10);

const markdown = [
  '# ' + title,
  '',
  '**Source:** ' + d.cleanUrl,
  d.channel ? '**Channel:** ' + d.channel : null,
  '**Video ID:** ' + d.videoId,
  d.language ? '**Language:** ' + d.language : null,
  '**Words:** ' + wordCount.toLocaleString() + '  (about ' + readingMinutes + ' min of speech)',
  '**Transcribed:** ' + stamp,
  '',
  '---',
  '',
  '## Transcript',
  '',
  bodyText,
  ''
].filter(Boolean).join('\n');

// Safe filename for Google Drive.
const safeTitle = title
  .replace(/[\\/:*?"<>|#]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 80) || d.videoId;

return [{
  json: {
    ...d,
    title,
    markdown,
    // The Convert to File node decodes its input as base64, so encode here.
    markdownBase64: Buffer.from(markdown, 'utf8').toString('base64'),
    wordCount,
    readingMinutes,
    fileName: stamp + ' - ' + safeTitle + '.md'
  }
}];

// One place to describe whatever went wrong, so the sheet always gets an answer.
const s = $('Settings').item.json;
let videoId = null;
try { videoId = $('Extract Video ID').item.json.videoId; } catch (e) {}

const reason = $json.failureReason
  || (typeof $json.text !== 'undefined' && !$json.text ? 'No transcript available. This video has captions turned off, or only auto captions in an unsupported language.' : null)
  || 'The transcript service returned status ' + ($json.statusCode ?? 'unknown') + '.';

return [{
  json: {
    videoUrl: s.videoUrl,
    videoId,
    status: 'Failed',
    reason
  }
}];
